        }
    }

    override fun apply(signalId: UInt, op: ChangeOp, reader: UndraReader) {
        try {
            when (signalId) {
                0u -> {
                    if (op == ChangeOp.FULL) {
                        val value = codecVecUpload.decode(reader)
                        reader.finish()
                        _uploads.value = value
                    } else if (op == ChangeOp.PATCH) {
                        val ops = KeyedPatch.decodePatch(reader, Upload)
                        reader.finish()
                        try {
                            _uploads.value = KeyedPatch.applyPatch(_uploads.value, ops)
                        } catch (e: WireException.PatchOutOfBounds) {
                            resync(0u)
                        }
                    }
                }
                else -> Unit
            }
        } catch (e: Exception) {
            core.report(e, "Uploads.apply(signal: $signalId)")
        }
    }

    /** Re-observes a signal whose mirror diverged from the core, to receive a full value. */
    private fun resync(signalId: UInt) {
        core.observe(handle, signalId, false)
        core.observe(handle, signalId, true)
    }

    companion object {
        /**
         * No uploads.
         * @throws UndraCallError if the core panics, refuses or cancels the call, or cannot be reached.
         */
        operator fun invoke(ctx: UndraCore = UndraCookbook.core): Uploads = create(ctx)

        /**
         * No uploads.
         * @throws UndraCallError if the core panics, refuses or cancels the call, or cannot be reached.
         */
        fun create(ctx: UndraCore = UndraCookbook.core): Uploads {
            val handle = ctx.constructObject(UndraIds.Objects.Uploads.TYPE_ID, UndraIds.Objects.Uploads.NEW, ByteArray(0))
            return ctx.adopt(handle, ::Uploads)
        }
    }
}

private val codecVecPost = Codecs.vec(Post)
private val codecOptionString = Codecs.option(Codecs.string)
private val codecVecDelta = Codecs.vec(Delta)
private val codecOptionU32 = Codecs.option(Codecs.u32)
private val codecVecRow = Codecs.vec(Row)
private val codecVecField = Codecs.vec(Field)
private val codecVecFieldError = Codecs.vec(FieldError)
private val codecVecUpload = Codecs.vec(Upload)
